{
  "comprehensible": "The results point to something but do not prove it, and they should not be understood as showing more than they do.",
  "glosses": [
    {
      "expression": "suggestive rather than conclusive",
      "gloss": "hinting at something but not proving it"
    },
    {
      "expression": "ought not to be over-read",
      "gloss": "should not be understood as meaning more than they really show"
    }
  ],
  "grammar": null,
  "translation": "这些发现只是提示性的，而非结论性的，不应被过度解读。"
}

{
  "comprehensible": "He was, to say it in a gentle way, not very pleased with the result.",
  "glosses": [
    {
      "expression": "to put it mildly",
      "gloss": "used to say that you are describing something in a gentler or less strong way than you could"
    },
    {
      "expression": "not best pleased",
      "gloss": "annoyed or unhappy; a polite or understated way of saying 'not pleased'"
    }
  ],
  "grammar": "The phrase 'to put it mildly' is a parenthetical comment inserted between 'was' and 'not best pleased'. It does not change the main grammar: the main clause is 'He was not best pleased with the outcome.' The comment only tells you that the speaker is choosing gentle words.",
  "translation": "说得委婉些，他对这个结果不太满意。"
}
